																				"ComputingTasks__": {
																					"type": "HTML",
																					"data": false,
																					"stamp": 144,
																					"options": {
																						"label": "_ComputingTasks",
																						"htmlContent": "<div class=\"WaitingIcon-Small\" style=\"width: 100%;\"></div>",
																						"width": "100%",
																						"hidden": true,
																						"version": 0
																					}
																				},
																				"ChartGantt__": {
																					"type": "HTML",
																					"data": false,
																					"stamp": 145,
																					"options": {
																						"label": "_chart",
																						"htmlContent": "<script>\n\tvar chart;\n\tvar currentChartDataInJSON = null; // to avoid updating the chart too frequently\n\tfunction updateData(event)\n\t{\n\t\tvar newChartDataInJSON = JSON.stringify(event.value.series[0].data);\n\t\tconst needsToCreate = !chart || chart.chartHeight !== event.value.chart.height;\n\t\tif (needsToCreate)\n\t\t{\n\t\t\tconst conf = {};\n\t\t\tObject.assign(conf, event.value);\n\t\t\tHighcharts.setOptions({ lang: event.value.lang });\n\t\t\tconf.tooltip.pointFormatter = function()\n\t\t\t{\n\t\t\t\tlet point = this,\n\t\t\t\t\tseries = point.series,\n\t\t\t\t\txAxis = series.xAxis,\n\t\t\t\t\tformats = series.tooltipOptions.dateTimeLabelFormats,\n\t\t\t\t\tstartOfWeek = xAxis.options.startOfWeek,\n\t\t\t\t\tttOptions = series.tooltipOptions,\n\t\t\t\t\tformat = formats.day,\n\t\t\t\t\tstart,\n\t\t\t\t\tend,\n\t\t\t\t\tmilestone = point.options.milestone,\n\t\t\t\t\tretVal = '<b>' + (point.name || point.yCategory) + '</b>';\n\n\t\t\t\tif (ttOptions.pointFormat)\n\t\t\t\t{\n\t\t\t\t\treturn point.tooltipFormatter(ttOptions.pointFormat);\n\t\t\t\t}\n\n\t\t\t\tif (!format && typeof point.start === \"number\")\n\t\t\t\t{\n\t\t\t\t\tformat = series.chart.time.getDateFormat(\n\t\t\t\t\t\txAxis.closestPointRange,\n\t\t\t\t\t\tpoint.start,\n\t\t\t\t\t\tstartOfWeek,\n\t\t\t\t\t\tformats || {}\n\t\t\t\t\t);\n\t\t\t\t}\n\n\t\t\t\tstart = series.chart.time.dateFormat(\n\t\t\t\t\tformat,\n\t\t\t\t\tpoint.start\n\t\t\t\t);\n\t\t\t\tend = series.chart.time.dateFormat(\n\t\t\t\t\tformat,\n\t\t\t\t\tpoint.end\n\t\t\t\t);\n\n\t\t\t\tretVal += '<br/>';\n\n\t\t\t\tif (!milestone)\n\t\t\t\t{\n\t\t\t\t\tretVal += conf.lang.start + start + '<br/>';\n\t\t\t\t\tretVal += conf.lang.end + end + '<br/>';\n\t\t\t\t} else\n\t\t\t\t{\n\t\t\t\t\tretVal += start + '<br/>';\n\t\t\t\t}\n\n\t\t\t\treturn retVal;\n\t\t\t};\n\t\t\tcurrentChartDataInJSON = newChartDataInJSON;\n\t\t\tchart = Highcharts.ganttChart(\"GanttChart-container\", conf);\n\t\t}\n\t\telse if (currentChartDataInJSON !== newChartDataInJSON)\n\t\t{\n\t\t\tcurrentChartDataInJSON = newChartDataInJSON;\n\t\t\t// we delay the chart redraw - recommended in the Highcharts documentation\n\t\t\tchart.series[0].setData(event.value.series[0].data, /*redraw:*/false);\n\t\t\tsetTimeout(() => chart.redraw());\n\t\t}\n\t\tthis.removeCollapseIconAndAction();\n\t}\n\n\tfunction removeCollapseIconAndAction()\n\t{\n\t\tsetTimeout(() =>\n\t\t{\n\t\t\t// Get the label which can be collapsed (site level)\n\t\t\tvar highchartsTreegridNodeLevel1Elements = this.getSvgElemByClass('highcharts-treegrid-node-level-1')\n\t\t\thighchartsTreegridNodeLevel1Elements.forEach((item) =>\n\t\t\t{\n\t\t\t\tif (item.hcEvents !== undefined)\n\t\t\t\t{\n\t\t\t\t\tif (item.hcEvents.click !== undefined)\n\t\t\t\t\t{\n\t\t\t\t\t\tif (item.hcEvents.click.length > 0)\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\titem.removeEventListener('click', item.hcEvents.click[0].fn)\n\t\t\t\t\t\t\titem.style.cursor = 'default'\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\tif (item.hcEvents.mouseover !== undefined)\n\t\t\t\t\t{\n\t\t\t\t\t\tif (item.hcEvents.mouseover.length > 0)\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\titem.removeEventListener('mouseover', item.hcEvents.mouseover[0].fn)\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t})\n\t\t\t// Get the icon in front which can be collapsed (site level)\n\t\t\tvar highchartsLabelIconElements = this.getSvgElemByClass('highcharts-label-icon')\n\t\t\thighchartsLabelIconElements.forEach((item) =>\n\t\t\t{\n\t\t\t\tif (item.hcEvents !== undefined)\n\t\t\t\t{\n\t\t\t\t\tif (item.hcEvents.click !== undefined)\n\t\t\t\t\t{\n\t\t\t\t\t\tif (item.hcEvents.click.length > 0)\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\titem.remove()\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t})\n\t\t}, 100)\n\t}\n\n\tfunction getSvgElemByClass(searchClass, node, tag) {\n\t\tconst classElements = []\n\t\tif (node == null) { node = document }\n\n\t\tif (tag == null) { tag = '*' }\n\n\t\t// SVG = XML, so we need the XML method:\n\t\t// using 'magic' namespace variable provided by websvg (svgns)\n\t\tconst els = node.getElementsByTagNameNS('http://www.w3.org/2000/svg', tag)\n\t\tconst elsLen = els.length\n\t\tvar pattern = new RegExp('(\\\\b)' + searchClass + '(\\\\b)')\n\t\tvar j = 0\n\t\tvar i = 0\n\t\tfor (i = 0; i < elsLen; i++)\n\t\t{\n\t\t\t// inspect\n\t\t\t// SVG specific helper\n\t\t\tif (els[i].hasAttribute('class') && pattern.test(els[i].getAttribute('class')))\n\t\t\t{\n\t\t\t\tclassElements[j] = els[i]\n\t\t\t\tj++\n\t\t\t} else if (pattern.test(els.className))\n\t\t\t{\n\t\t\t\tclassElements[j] = els[i]\n\t\t\t\tj++\n\t\t\t}\n\t\t}\n\n\t\treturn classElements\n\t}\n</script>\n<div id=\"GanttChart-container\"></div>\n<span id=\"handler\" style=\"display: none\" onclick=\"updateData(event)\"></span>",
